import sys
sys.setrecursionlimit(200000)

class Node:
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None

def build_tree(nodes, index):
    if index >= len(nodes) or nodes[index] is None:
        return None
    root = Node(nodes[index])
    root.left = build_tree(nodes, 2 * index + 1)
    root.right = build_tree(nodes, 2 * index + 2)
    return root

def solve(root):
    count = 0

    def dfs(node):
        nonlocal count
        if not node:
            return 0

        left = dfs(node.left)
        right = dfs(node.right)

        if left == -1 or right == -1:
            count += 1
            return 1

        if left == 1 or right == 1:
            return 0

        return -1

    dfs(root)
    return count

def main():
    try:
        lines = sys.stdin.read().split()
    except Exception:
        return

    if not lines:
        return

    n = int(lines[0])

    if n == 0:
        print(0)
        return

    nodes = []
    idx = 1
    for _ in range(n):
        if idx < len(lines):
            val = lines[idx]
            nodes.append(int(val) if val != 'null' else None)
            idx += 1
        else:
            nodes.append(None)

    root = build_tree(nodes, 0)
    if root is None:
        print(0)
        return

    result = solve(root)
    print(result)

if __name__ == "__main__":
    main()
